(function(){
  var BG = "data:image/jpeg;base64,";

  // Progressive word list. Tiers: A/B = exact letters only. C = +1 decoy. D = +2 decoys.
  var WORDS = [
    // Tier A
    {w:"cat", e:"\uD83D\uDC31"}, {w:"sun", e:"\u2600\uFE0F"}, {w:"dog", e:"\uD83D\uDC36"},
    {w:"frog", e:"\uD83D\uDC38"}, {w:"star", e:"\u2B50"}, {w:"jump", e:"\uD83E\uDD38"},
    {w:"nest", e:"\uD83E\uDEBA"}, {w:"blue", e:"\uD83D\uDD35"},
    // Tier B
    {w:"happy", e:"\uD83D\uDE0A"}, {w:"tiger", e:"\uD83D\uDC2F"}, {w:"cloud", e:"\u2601\uFE0F"},
    {w:"plant", e:"\uD83C\uDF31"}, {w:"river", e:"\uD83C\uDF0A"}, {w:"storm", e:"\u26C8\uFE0F"},
    {w:"eagle", e:"\uD83E\uDD85"}, {w:"brave", e:"\uD83D\uDCAA"},
    // Tier C (+1 decoy)
    {w:"forest", e:"\uD83C\uDF32"}, {w:"planet", e:"\uD83E\uDE90"}, {w:"dragon", e:"\uD83D\uDC09"},
    {w:"castle", e:"\uD83C\uDFF0"}, {w:"wonder", e:"\u2728"}, {w:"silver", e:"\uD83E\uDD48"},
    {w:"purple", e:"\uD83D\uDFE3"}, {w:"thunder", e:"\u26A1"},
    // Tier D (+2 decoys)
    {w:"rainbow", e:"\uD83C\uDF08"}, {w:"mountain", e:"\uD83C\uDFD4\uFE0F"}, {w:"treasure", e:"\uD83D\uDCB0"},
    {w:"elephant", e:"\uD83D\uDC18"}, {w:"universe", e:"\uD83C\uDF0C"}, {w:"adventure", e:"\uD83E\uDDED"}
  ];

  var SLOTS = [
    [30,12],[48,10],[62,18],[38,28],[55,30],[28,42],[45,48],[60,45],
    [35,60],[50,62],[65,63],[28,75],[48,78],[58,88]
  ];

  function tierFor(i){
    var p = i % WORDS.length;
    if(p < 8) return 0;
    if(p < 16) return 0;
    if(p < 24) return 1;
    return 2;
  }
  function decoyCountFor(tier){ return tier===0?0:(tier===1?1:2); }

  function shuffle(arr){
    var a = arr.slice();
    for(var i=a.length-1;i>0;i--){
      var j = Math.floor(Math.random()*(i+1));
      var t=a[i]; a[i]=a[j]; a[j]=t;
    }
    return a;
  }

  var ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  function pickDecoys(count, excludeLetters){
    var out = [];
    var tries = 0;
    while(out.length < count && tries < 200){
      tries++;
      var ch = ALPHA[Math.floor(Math.random()*ALPHA.length)];
      if(excludeLetters.indexOf(ch) === -1 && out.indexOf(ch) === -1) out.push(ch);
    }
    return out;
  }

  function start(host, ctx){
    ctx.state.poolProgress = ctx.state.poolProgress || {wordIndex:0};
    var SESSION_TOTAL = 5;

    var gs = {
      sessionIdx: 0,
      firstTryOK: 0,
      wordIndex: ctx.state.poolProgress.wordIndex || 0,
      attempts: 0,
      hintUsed: false,
      tiles: [],
      blanks: [],
      round: null
    };

    function buildRound(){
      var entry = WORDS[gs.wordIndex % WORDS.length];
      var tier = tierFor(gs.wordIndex);
      var word = entry.w.toUpperCase();
      var letters = word.split("");
      var decoys = pickDecoys(decoyCountFor(tier), letters);
      var tileDefs = letters.map(function(ch,i){ return {id:"L"+i, letter:ch, used:false}; })
        .concat(decoys.map(function(ch,i){ return {id:"D"+i, letter:ch, used:false}; }));
      var tiles = shuffle(tileDefs);
      var slots = shuffle(SLOTS).slice(0, tiles.length);
      tiles.forEach(function(t,i){ t.x = slots[i][0]; t.y = slots[i][1]; t.tube = i%2===0 ? "blue" : "yellow"; });
      gs.round = {word:word, emoji:entry.e};
      gs.tiles = tiles;
      gs.blanks = letters.map(function(){ return null; });
      gs.attempts = 0;
      gs.hintUsed = false;
    }

    function selectTile(id){
      var tile = gs.tiles.find(function(t){ return t.id===id; });
      if(!tile || tile.used) return;
      var idx = gs.blanks.indexOf(null);
      if(idx === -1) return;
      gs.blanks[idx] = id;
      tile.used = true;
      render();
    }

    function removeBlank(idx){
      var id = gs.blanks[idx];
      if(id == null) return;
      var tile = gs.tiles.find(function(t){ return t.id===id; });
      if(tile) tile.used = false;
      gs.blanks[idx] = null;
      render();
    }

    function submit(){
      if(gs.blanks.indexOf(null) !== -1){
        ctx.toast && ctx.toast("Fill in all the blanks first!");
        return;
      }
      gs.attempts++;
      var guess = gs.blanks.map(function(id){
        return gs.tiles.find(function(t){ return t.id===id; }).letter;
      }).join("");

      if(guess === gs.round.word){
        if(gs.attempts === 1) gs.firstTryOK++;
        ctx.award({coins:5});
        ctx.confetti && ctx.confetti();
        ctx.toast && ctx.toast("Splash! You got it!");
        gs.sessionIdx++;
        gs.wordIndex++;
        ctx.state.poolProgress.wordIndex = gs.wordIndex;
        if(gs.sessionIdx >= SESSION_TOTAL){
          renderComplete();
        } else {
          buildRound();
          render();
        }
      } else {
        gs.tiles.forEach(function(t){ t.used = false; });
        gs.blanks = gs.blanks.map(function(){ return null; });
        render(true);
      }
    }

    function useHint(){
      if(gs.hintUsed) return;
      gs.hintUsed = true;
      render();
    }

    function tubeHTML(t){
      var left = t.used ? "" : (
        '<div class="pw-tube pw-'+t.tube+'" data-id="'+t.id+'" style="left:'+t.x+'%;top:'+t.y+'%;animation-duration:'+(2.4+Math.random()*1.2).toFixed(2)+'s;animation-delay:-'+(Math.random()*2).toFixed(2)+'s;">'+t.letter+'</div>'
      );
      return left;
    }

    function blankHTML(idx){
      var id = gs.blanks[idx];
      var letter = "";
      if(id != null){
        var tile = gs.tiles.find(function(t){ return t.id===id; });
        letter = tile ? tile.letter : "";
      }
      return '<div class="pw-blank'+(letter?" pw-filled":"")+'" data-idx="'+idx+'">'+letter+'</div>';
    }

    function styleBlock(){
      return '<style>'
        + '.pw-wrap{max-width:520px;margin:0 auto;}'
        + '.pw-blanks{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin:10px 0 14px;}'
        + '.pw-blank{width:38px;height:44px;border-radius:8px;background:#fff;border:3px solid #cfd8bd;display:flex;align-items:center;justify-content:center;font-family:Fredoka,sans-serif;font-weight:700;font-size:22px;color:#33433a;cursor:pointer;}'
        + '.pw-blank.pw-filled{border-color:#62CBC9;background:#eafcfb;}'
        + '.pw-stage{position:relative;width:100%;padding-top:71.6%;border-radius:16px;overflow:hidden;background-image:url(' + BG + ');background-size:cover;background-position:center;box-shadow:0 10px 24px -12px rgba(30,40,20,.4);margin-bottom:12px;}'
        + '.pw-tube{position:absolute;width:54px;height:54px;margin-left:-27px;margin-top:-27px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:Fredoka,sans-serif;font-weight:700;font-size:22px;color:#0c2b3a;cursor:pointer;box-shadow:0 5px 10px rgba(0,0,0,.28);animation-name:pwBob;animation-timing-function:ease-in-out;animation-iteration-count:infinite;user-select:none;}'
        + '.pw-blue{background:radial-gradient(circle,#eaf7ff 30%,#2f8fd1 34%,#2f8fd1 62%,#eaf7ff 66%);}'
        + '.pw-yellow{background:radial-gradient(circle,#fff9e6 30%,#f2b705 34%,#f2b705 62%,#fff9e6 66%);}'
        + '@keyframes pwBob{0%{transform:translateY(0) rotate(-4deg);}50%{transform:translateY(-9px) rotate(4deg);}100%{transform:translateY(0) rotate(-4deg);}}'
        + '.pw-hintbox{text-align:center;font-size:34px;margin:4px 0;min-height:40px;}'
        + '@media (prefers-reduced-motion:reduce){.pw-tube{animation:none;}}'
        + '</style>';
    }

    function render(wasWrong){
      var blanksHTML = gs.blanks.map(function(_,i){ return blankHTML(i); }).join("");
      var tubesHTML = gs.tiles.map(tubeHTML).join("");
      var hintHTML = gs.hintUsed ? ('<div class="pw-hintbox">'+gs.round.emoji+'</div>') : "";
      host.innerHTML =
        styleBlock() +
        '<div class="pw-wrap">' +
          '<p class="sub center">Clover needs help spelling a word! Tap the tubes to fill the blanks.</p>' +
          '<div class="pw-blanks">' + blanksHTML + '</div>' +
          '<div class="pw-stage">' + tubesHTML + '</div>' +
          (wasWrong ? '<p class="fb no center">Not quite — the tubes floated back. Try again!</p>' : '') +
          hintHTML +
          '<div class="row center mt">' +
            '<button class="btn ghost sm" id="pwHint"'+(gs.hintUsed?' disabled':'')+'>Hint '+"\uD83D\uDCA1"+'</button>' +
            '<button class="btn green" id="pwSubmit">Submit</button>' +
          '</div>' +
          '<p class="hint center mt">Word ' + (gs.sessionIdx+1) + ' of ' + SESSION_TOTAL + '</p>' +
          '<div class="row center mt"><button class="btn teal sm" id="pwClose">\u2190 Map</button></div>' +
        '</div>';

      gs.tiles.forEach(function(t){
        if(t.used) return;
        var el = host.querySelector('[data-id="'+t.id+'"]');
        if(el) el.addEventListener('pointerup', function(){ selectTile(t.id); });
      });
      gs.blanks.forEach(function(_,i){
        var el = host.querySelector('.pw-blank[data-idx="'+i+'"]');
        if(el) el.addEventListener('pointerup', function(){ removeBlank(i); });
      });
      var hintBtn = host.querySelector('#pwHint');
      if(hintBtn) hintBtn.addEventListener('pointerup', useHint);
      var submitBtn = host.querySelector('#pwSubmit');
      if(submitBtn) submitBtn.addEventListener('pointerup', submit);
      var closeBtn = host.querySelector('#pwClose');
      if(closeBtn) closeBtn.addEventListener('pointerup', function(){ ctx.close(); });
    }

    function renderComplete(){
      var earnedStar = gs.firstTryOK >= 4;
      ctx.award({coins: earnedStar ? 10 : 0, star: earnedStar});
      ctx.confetti && ctx.confetti();
      host.innerHTML =
        '<div class="center">' +
          '<img src="' + ctx.clover.cele + '" alt="Clover celebrating" style="width:120px;height:auto;margin:8px auto;display:block;" />' +
          '<h2 class="h2">Great spelling, Eliza!</h2>' +
          '<p class="sub">You helped Clover spell ' + SESSION_TOTAL + ' words at the pool.' +
          (earnedStar ? ' You earned a star! \u2B50' : ' Come back and try for a star next time!') + '</p>' +
          '<div class="row center mt">' +
            '<button class="btn green" id="pwAgain">Spell More Words</button>' +
            '<button class="btn teal" id="pwDone">Done for now</button>' +
          '</div>' +
        '</div>';
      var again = host.querySelector('#pwAgain');
      if(again) again.addEventListener('pointerup', function(){
        gs.sessionIdx = 0;
        gs.firstTryOK = 0;
        buildRound();
        render();
      });
      var done = host.querySelector('#pwDone');
      if(done) done.addEventListener('pointerup', function(){ ctx.close(); });
    }

    buildRound();
    render();
  }

  window.Stops.register('9A', { name:'Pool', start });
})();
